import json
from pathlib import Path
cases=json.loads(Path('.ufo/waves/round-60/challenge.json').read_text())
answers=[]
binding={'source':'corpus/source-snapshots/round-60/S094.txt','sha256':'78194d2b4a826311cbb3ff9e2186036207d6ca3995f86235b9d73cb38773cb25','table':'Table of Values, zero-based Row','model':'ssvc:DT_DP:1.0.0','inputs':['ssvc:E:1.1.0','ssvc:EXP:1.0.1','ssvc:A:2.0.0','ssvc:HI:2.0.2'],'components':['ssvc:MI:2.0.0','ssvc:SI:2.0.1'],'outcomes':'ssvc:DSOI:1.0.0','conflict':'Explicit table governs this bounded result. S094:510 none+very-high summary is broader than rows3/7/11/15/19; no claim that prose agrees.'}
def inp(value,quote,reason,missing=()):
 return {'value':value,'evidence':[quote] if isinstance(quote,str) else quote,'reasoning':reason,'missing':list(missing)}
def add(n,unit,e,x,a,h,p,rows,unsupported):
 c=cases[n-1]; d={'id':c['id'],'model_id':'ssvc:DT_DP:1.0.0','model_binding':binding,'stakeholder_unit':unit,'inputs':{'exploitation':e,'exposure':x,'automatable':a,'human_impact':h},'priority':p,'path_rows':rows,'unsupported_conclusions':unsupported}
 for v in d['inputs'].values():
  for q in v['evidence']: assert q in c['scenario'],(c['id'],q)
 answers.append(d)
wild='Credible public incident reports provide shared, reliable observations of real attackers using this flaw in the wild.'
opened='The affected service is reachable over the public Internet, with no plausible restriction or effective access control on the vulnerable path.'
auto='Independent analysis establishes reliable automation of discovering suitable targets, preparing the payload, delivering it, and triggering exploitation.'
local='The affected program runs only locally on a physically isolated workstation, on no network; the assessment establishes a highly controlled attack surface.'
noauto='Payload delivery necessarily requires an individual human to perform a fresh physical procedure at each target; the analysis establishes that this required step cannot reliably be automated.'
ms='The impact study finds that a service directly supporting mission-essential functions becomes unusable, although the essential functions themselves continue temporarily.'
critical='One person could die; the study excludes multiple deaths, operator incapacitation, total system loss, ecosystem collapse and social-system collapse, and finds no higher consequence in another safety dimension.'
deg='The impact study finds only brief degradation of a non-essential reporting function; every mission-essential function continues.'
minor='Across physical, operator, system-resilience, environmental, financial and psychological safety effects, the study bounds all consequences at minor effects or less.'
E=lambda:inp('active',wild,'S094 E1.1.0: credible shared observed use by real attackers establishes active, not just availability of a PoC.')
O=lambda:inp('open',opened,'S094 EXP1.0.1: the actual vulnerable path is publicly reachable without plausible restriction, establishing open.')
S=lambda:inp('small',local,'S094 EXP1.0.1: local-only physically isolated, highly controlled attack surface establishes small; not merely a firewall label.')
Y=lambda:inp('yes',auto,'S094 A2.0.0: the analysis establishes reliable automation of all four initial stages: reconnaissance, weaponization, delivery and exploitation.')
N=lambda:inp('no',noauto,'S094 A2.0.0 requires all four stages; necessarily fresh per-target physical delivery is affirmatively non-automatable, so no. This is not inferred just from a manual demonstration.')
H=lambda:inp('high',[ms,critical],'S095 MI2.0.0 support crippled: directly supporting service unusable while MEFs continue. S096 SI2.0.1 critical: one death with higher dimensions expressly excluded. S094 HI2.0.2 critical AND support crippled yields high, not catastrophic/very high.')
L=lambda:inp('low',[deg,minor],'S095 MI2.0.0 degraded: only non-essential function degradation. Safety effects are bounded to negligible under S096 SI2.0.1, not simply omitted. S094 HI2.0.2 negligible safety AND degraded mission yields low.')
add(1,'Harbor operations as deployer, supplier patch paired to deployed Delta H-7.',E(),O(),Y(),H(),'immediate',[70],['CVSS9.8 alone did not determine priority; row70 follows active/open/yes/high.','This fictional table result is not a live instruction, supplier release urgency or proof that an actual finding exists.'])
add(2,'Archive services as deployer, supplier patch paired to deployed Delta A-3.',E(),S(),Y(),L(),'scheduled',[52],['Same flaw and CVSS9.8 as Harbor does not imply same stakeholder priority: row52 differs from row70 because exposure and human impact differ.','Do not infer lack of automation merely from isolation; the scenario independently establishes reliable automation.','Scheduled does not mean safe or action authorized.'])
add(3,'Museum operations as deployer, supplied patch paired to instance M-8.',inp('public poc','A sufficiently thorough current evidence review finds no reliable indication of real-world exploitation and no published exploit program, but establishes that the vulnerability has a well-known exploitation method.','S094 E1.1.0 public PoC has an alternative limb: a well-known exploitation method. No published program does not make none when that limb holds; thorough review supplies no active evidence.'),O(),N(),inp('medium',['One essential catalog function fails longer than the museum considers acceptable; its overall mission can still be carried out for a time.','Safety analysis finds that exploitation eliminates a safety margin without actual harm, and explicitly excludes any more serious safety effect in every dimension.'],'S095 MI2.0.0 MEF failure: one essential function exceeds acceptable interruption, overall mission persists. S096 SI2.0.1 marginal: safety margin eliminated without actual harm. S094 HI2.0.2 marginal AND MEF failure yields medium.'),'scheduled',[41],['No exploit program is not no public-PoC classification; well-known-method alternative applies.','One MEF failure is not whole-mission failure; manual delivery is necessary here, not merely the chosen laboratory workflow.'])
add(4,'Transit office as deployer, supplied patch paired to instance T-1.',inp('none','A thorough current review finds neither evidence of active exploitation nor a public proof of concept nor a well-known exploitation method.','S094 E1.1.0 none is supported by the explicit thorough negative review, not by missing text.'),S(),N(),inp('very high',['Exploitation would disable multiple essential functions and impair recovery until the office cannot deliver its overall mission.','Safety analysis bounds all safety effects at minor or less.'],'S095 MI2.0.0 mission failure established by multiple essential failures, impaired recovery and inability to deliver mission. S096 SI2.0.1 safety is bounded negligible. S094 HI2.0.2 mission-failure OR catastrophic-safety means very high even though safety is minor.'),'scheduled',[3],['Do not replace explicit row3 with out-of-cycle using S094:510 overbroad prose. Model/table pin and discrepancy are disclosed.','Very high HI does not mechanically impose immediate, and none does not mean no possible harm.'])
add(5,'Factory planning as deployer, supplied patch paired to instance F-4.',E(),inp('controlled','The networked service has restrictions that demonstrably interrupt this attack reliably and soon enough; it is neither publicly unrestricted nor a local-only/highly-controlled isolated system.','S094 EXP1.0.1 controlled is supported by effective timely attack interruption and restrictions; explicit exclusions distinguish open/small.'),inp('insufficient','No assessment of whether all four attack stages can reliably be automated has been supplied.','S094 A2.0.0 cannot be assigned yes or no without reliable four-stage capability evidence. Enumerate both values, not a default.', ['Can an attacker reliably automate all four initial attack stages, or is at least one necessarily non-automatable?']),H(),'out-of-cycle',[58,62],['Unknown automation remains unknown. Row58 active/controlled/no/high and row62 active/controlled/yes/high both give out-of-cycle, so priority is determinate without inventing automation.','Do not use an all-insufficient answer to erase known facts/common result.'])
add(6,'Library network as deployer, supplied patch paired to instance L-2.',inp('insufficient','The exploitation-evidence section was accidentally omitted: nothing in this dossier establishes existence or absence of a public proof of concept, a well-known method, or exploitation by attackers.','S094 E1.1.0: omitted review is not none. None, public poc and active all remain compatible.', ['What reliable current review establishes active wild use, public PoC/well-known method, or their absence?']),O(),Y(),L(),'insufficient',[20,44,68],['Rows20 and44 scheduled versus68 out-of-cycle: no common priority.','Automation is separately established; do not treat that as evidence of public release or observed wild use.','Omitted section cannot be silently repaired with none.'])
add(7,'Cinema services as deployer, supplied patch paired to instance C-5.',inp('public poc','A current review finds a public proof of concept and expressly finds no reliable evidence of in-the-wild exploitation.','S094 E1.1.0 public PoC supported, active not supported by the current review.'),O(),inp('insufficient',['A laboratory has automated triggering the flaw after an operator manually selects a target and prepares and delivers a payload.','Whether selection, payload preparation and delivery could reliably be automated is unassessed, not demonstrated impossible.'],'S094 A2.0.0 asks reliable automation capability of all four stages. Actual manual choices prove neither necessity nor impossibility, and one automated final stage proves neither whole-chain yes nor no.', ['Can reconnaissance, weaponization and delivery reliably be automated, or is any one necessarily non-automatable?']),H(),'insufficient',[42,46],['Rows42 public-poc/open/no/high scheduled and46 public-poc/open/yes/high out-of-cycle disagree.','Do not infer no from what this operator happened to do; R67 possession/necessity lesson generalizes to chosen/required manual actions.'])
mismatch='Distributor R is actually asking for its supplier-side urgency to develop and release a patch, not urgency to apply a supplied patch to its own deployed instance.'
